def card(d):
 return f'''<article class="news-card"><a class="card-image {'logo-image' if 'logo' in d['image'] else ''}" href="{d['slug']}.html"><img src="{d['image']}" alt="{'Símbolo do Grupo Escoteiro Marechal Rondon' if 'logo' in d['image'] else 'Cerimônia ao ar livre registrada pelo grupo'}" loading="lazy"><span>{d['category']}</span></a><div class="card-body"><small>{d['date']}</small><h3><a href="{d['slug']}.html">{d['title']}</a></h3><a class="text-link" href="{d['slug']}.html">Ler história <span aria-hidden="true">↗</span></a></div></article>'''
def head(title,active=''):
 return f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Marechal Rondon 194/SP</title><meta name="description" content="Escotismo, amizade e vida ao ar livre em São João da Boa Vista. Conheça o Grupo Escoteiro Marechal Rondon 194/SP, desde 1969."><meta name="theme-color" content="#123c31"><link rel="icon" href="assets/logo.png"><link rel="stylesheet" href="style.css"><script defer src="app.js"></script></head><body><a class="skip" href="#conteudo">Ir para o conteúdo</a><div class="topbar">SÃO JOÃO DA BOA VISTA · SP <span>Desde 1969, sempre alerta.</span></div><header><a class="brand" href="index.html"><img src="assets/logo.png" alt="Emblema do grupo"><span>MARECHAL RONDON<small>GRUPO ESCOTEIRO · 194/SP</small></span></a><button class="menu-button" aria-expanded="false" aria-controls="menu">Menu ☰</button><nav id="menu" aria-label="Navegação principal">{''.join(f'<a href="{u}" '+('aria-current="page"' if active==u else '')+f'>{n}</a>' for u,n in [('grupo.html','Nosso grupo'),('ramos.html','Ramos'),('novidades.html','Novidades'),('participar.html','Participe')])}<a class="nav-support" href="apoie.html">Apoie o grupo <span aria-hidden="true">↗</span></a></nav></header><main id="conteudo">'''
def foot():
 return f'''</main><footer><div class="footer-top"><div><a class="brand" href="index.html"><img src="assets/logo.png" alt=""><span>MARECHAL RONDON<small>GRUPO ESCOTEIRO · 194/SP</small></span></a><p>Boas histórias começam com<br>gente disposta a fazer o bem.</p></div><div><h3>Explore</h3><a href="grupo.html">Nossa história</a><a href="ramos.html">Ramos</a><a href="novidades.html">Diário de atividades</a><a href="galeria.html">Galeria</a><a href="agenda.html">Agenda e eventos</a></div><div><h3>Faça parte</h3><a href="participar.html">Conheça o grupo</a><a href="apoie.html">Como apoiar</a><a href="contato.html">Localização e contato</a><a href="documentos.html">Informações institucionais</a></div><div><h3>Encontre a gente</h3><p>Av. Jorge Estevam Rodrigues, 1725<br>Parque das Bromélias<br>São João da Boa Vista · SP</p><a href="{IG}" target="_blank" rel="noopener">Instagram ↗</a></div></div><div class="footer-bottom"><span>© {2026} Grupo Escoteiro Marechal Rondon — 194/SP</span><a href="privacidade.html">Privacidade e imagens</a><span>Sempre alerta. Sempre juntos.</span></div></footer><dialog id="photo-dialog"><button class="close-dialog" aria-label="Fechar imagem">×</button><img alt=""><p></p></dialog></body></html>'''
def write(name,title,body,active=''): (p/name).write_text(head(title,active)+body+foot())
def intro(k,t,d): return f'<section class="page-intro wrap"><p class="eyebrow">{k}</p><h1>{t}</h1><p class="lead">{d}</p></section>'
write('index.html','A aventura de crescer juntos','''<section class="hero"><div class="hero-copy"><p class="eyebrow light">ESCOTISMO EM SÃO JOÃO DA BOA VISTA</p><h1>A aventura de<br>crescer <em>juntos.</em></h1><p>Um mundo de descobertas, amizades e boas ações. Há mais de cinco décadas, construímos essa história com os jovens da nossa cidade.</p><div class="actions"><a class="button orange" href="participar.html">Venha conhecer o grupo ↗</a><a class="hero-link" href="grupo.html">Nossa história</a></div><div class="hero-foot"><span class="star">✳</span><span>Vida ao ar livre.<br>Valores para a vida inteira.</span><span class="year">194<small>/ SP</small></span></div></div><div class="hero-photo"><img src="assets/equipe.jpg" alt="Integrantes do Marechal Rondon em cerimônia ao ar livre"><div class="photo-caption"><span>O NOSSO LUGAR É JUNTOS</span><small>Registro do grupo · 2026</small></div><div class="anniversary"><strong>57</strong><span>ANOS DE<br>HISTÓRIAS</span></div></div></section><div class="values-strip"><span>APRENDER FAZENDO</span><b>✳</b><span>AMIZADES PARA A VIDA</span><b>✳</b><span>SERVIR À COMUNIDADE</span><b>✳</b><span>EXPLORAR A NATUREZA</span></div><section class="wrap section intro-grid"><div><p class="eyebrow">UM GRUPO. MUITAS DESCOBERTAS.</p><h2>Mais que uma atividade.<br>Um lugar para pertencer.</h2></div><div><p>Somos o Grupo Escoteiro Marechal Rondon — 194/SP. Desde 19 de abril de 1969, reunimos crianças, jovens e adultos voluntários em São João da Boa Vista.</p><p>Entre desafios, brincadeiras e boas ações, cada experiência é uma oportunidade de aprender, cuidar do outro e descobrir do que somos capazes.</p><a class="text-link" href="grupo.html">Conheça quem faz essa história ↗</a></div></section><section class="section pale"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">NOSSO DIÁRIO</p><h2>O que acontece por aqui.</h2></div><a class="text-link" href="novidades.html">Todas as novidades ↗</a></div><div class="cards">'''+''.join(card(d) for d in posts[:3])+'''</div></div></section><section class="wrap section"><div class="section-heading"><div><p class="eyebrow">CADA ETAPA, NOVAS DESCOBERTAS</p><h2>Uma aventura que cresce com você.</h2></div><a class="text-link" href="ramos.html">Conheça os ramos ↗</a></div><div class="branches"><a href="ramos.html#lobinho" class="branch yellow"><span>01 / LOBINHO</span><h3>Imaginar.<br>Brincar. Descobrir.</h3><p>Aprendizados que começam com uma boa brincadeira.</p><b>Melhor possível ↗</b></a><a href="ramos.html#escoteiro" class="branch green"><span>02 / ESCOTEIRO</span><h3>Explorar.<br>Aprender. Cooperar.</h3><p>A vida em patrulha transforma desafios em conquistas.</p><b>Sempre alerta ↗</b></a><a href="ramos.html#senior" class="branch red"><span>03 / SÊNIOR</span><h3>Desafiar.<br>Criar. Superar.</h3><p>Autonomia e responsabilidade para ir mais longe.</p><b>Sempre alerta ↗</b></a><a href="ramos.html#pioneiro" class="branch blue"><span>04 / PIONEIRO</span><h3>Escolher.<br>Agir. Transformar.</h3><p>Projetos e serviço para deixar uma contribuição.</p><b>Servir ↗</b></a></div></section><section class="impact"><div class="wrap impact-grid"><div><p class="eyebrow light">PEQUENAS AÇÕES. MUDANÇAS REAIS.</p><h2>O mundo melhor<br>começa <em>bem aqui.</em></h2><p>Campanhas solidárias, cuidado com o ambiente e serviço à comunidade fazem parte da nossa caminhada.</p><a class="button cream" href="projetos.html">Conheça nossas ações ↗</a></div><div class="impact-list"><article><span>01</span><div><h3>Coleta de óleo usado</h3><p>Um destino adequado para o óleo e uma atitude de cuidado com o ambiente.</p></div></article><article><span>02</span><div><h3>Solidariedade em movimento</h3><p>Arrecadações que aproximam os jovens das necessidades da comunidade.</p></div></article><article><span>03</span><div><h3>Gente que faz a diferença</h3><p>Adultos voluntários que compartilham tempo, conhecimento e dedicação.</p></div></article></div></div></section><section class="wrap section support-banner"><div><p class="eyebrow">FAÇA PARTE DESSA HISTÓRIA</p><h2>Você também pode<br>ajudar a próxima aventura.</h2><p>Seu apoio se transforma em materiais, cuidado com a sede e experiências educativas.</p></div><a class="button green-button" href="apoie.html">Quero apoiar o Rondon ↗</a></section>''')
write('grupo.html','Nosso grupo',intro('DESDE 1969','Uma história feita de pessoas.','Jovens, famílias e voluntários unidos pelo escotismo em São João da Boa Vista.')+'''<section class="wrap split section"><img class="feature-photo" src="assets/equipe.jpg" alt="Cerimônia do grupo em ambiente natural"><div><p class="eyebrow">MARECHAL RONDON · 194/SP</p><h2>Raízes na cidade.<br>Olhos no futuro.</h2><p>O Grupo Escoteiro Marechal Rondon foi fundado em 19 de abril de 1969. Sua trajetória atravessa gerações e mantém vivo o encontro entre educação, natureza e serviço.</p><p>O nome homenageia Marechal Cândido Mariano da Silva Rondon. Entre os fundadores mencionados nos registros históricos estão Milton Ribeiro e sua esposa, José Wilson de Souza, o Tupi, e Benedito Juvêncio.</p></div></section><section class="pale section"><div class="wrap"><p class="eyebrow">NOSSA CAMINHADA</p><h2>O tempo passa. Os valores ficam.</h2><div class="timeline">'''+''.join(f'<article><strong>{y}</strong><div><h3>{t}</h3><p>{d}</p></div></article>' for y,t,d in [('1969','O começo de tudo','Fundação em 19 de abril, em São João da Boa Vista.'),('1994','Reconhecimento municipal','Reconhecimento de utilidade pública, referenciado na Lei municipal nº 140/1994.'),('2016','Um espaço para continuar','Lei municipal autoriza o uso de área no Parque das Bromélias.'),('2019','Cinco décadas de história','Celebração dos 50 anos e recebimento do Troféu Jatobá.'),('2026','A história continua','57 anos, novas atividades e uma diretoria eleita para o mandato até janeiro de 2028.')])+'''</div></div></section><section class="wrap section"><p class="eyebrow">QUEM AJUDA A CONSTRUIR</p><h2>Nossa diretoria.</h2><p>Mandato informado na assembleia de janeiro de 2026: até janeiro de 2028.</p><div class="people">'''+''.join(f'<article><span>{ini}</span><h3>{n}</h3><p>{r}</p></article>' for ini,n,r in [('UV','Ulisses Valin','Diretor-presidente'),('PH','Pedro Hernandez','Diretor administrativo'),('MZ','Mariana Zorgetto','Diretora financeira')])+'''</div><div class="note"><h3>Comissão Fiscal</h3><p>Fabio Mucin · Marta Bonfante · Luis Fernando Silvestre</p></div><a class="text-link" href="documentos.html">Fontes e informações institucionais ↗</a></section>''','grupo.html')
write('ramos.html','Nossos ramos',intro('CRESCER NO ESCOTISMO','Cada etapa tem a sua aventura.','Da descoberta pela brincadeira aos projetos de serviço, o escotismo acompanha o desenvolvimento dos jovens.')+'<section class="wrap">'+''.join(f'<article id="{slug}" class="branch-detail"><span class="branch-number">0{i}</span><div><p class="eyebrow">{lema}</p><h2>Ramo {name}</h2><p class="lead">{desc}</p><p>{text}</p><a class="text-link" href="participar.html">Converse com a equipe sobre o ingresso ↗</a></div></article>' for i,slug,name,lema,desc,text in [(1,'lobinho','Lobinho','MELHOR POSSÍVEL','O mundo é uma grande descoberta.','Brincadeiras, histórias, convivência e pequenas responsabilidades ajudam as crianças a aprender com alegria e cooperação.'),(2,'escoteiro','Escoteiro','SEMPRE ALERTA','Juntos, os desafios viram aprendizado.','A vida em patrulha, as atividades ao ar livre e a participação nas decisões favorecem a autonomia, a amizade e a responsabilidade.'),(3,'senior','Sênior','SEMPRE ALERTA','Mais autonomia. Novos horizontes.','Desafios, projetos e experiências em equipe convidam os jovens a conhecer suas capacidades e assumir responsabilidades.'),(4,'pioneiro','Pioneiro','SERVIR','Escolhas que deixam uma contribuição.','O serviço, os projetos e a reflexão sobre os próprios caminhos fazem parte de uma etapa de participação ativa na comunidade.')])+'</section><section class="wrap section"><div class="note"><h3>Qual é a melhor etapa para começar?</h3><p>Informe a idade do interessado à equipe. O grupo orientará sobre o ramo adequado, as vagas e as atividades disponíveis.</p><a class="button green-button" href="contato.html">Falar com o grupo ↗</a></div></section>','ramos.html')
write('novidades.html','Diário de atividades',intro('NOSSO DIÁRIO','Histórias de quem vive a aventura.','Atividades de fim de semana, encontros especiais, conquistas e boas ações do Marechal Rondon.')+'<section class="wrap section no-top"><div class="filters" aria-label="Filtrar notícias">'+''.join(f'<button data-filter="{c}" aria-pressed="{str(c=="Todas").lower()}">{c}</button>' for c in ['Todas','Atividades','Formação','Comunidade','Nosso grupo','Conquistas'])+'</div><div class="cards news-grid">'+''.join('<div data-category="'+d['category']+'">'+card(d)+'</div>' for d in posts)+'</div><p class="muted">Relatos elaborados a partir das publicações do grupo. As fontes originais estão em cada notícia.</p></section>','novidades.html')
for d in posts:
 write(d['slug']+'.html',d['title'],f'<article class="wrap story"><a class="text-link" href="novidades.html">← Voltar ao diário</a><p class="eyebrow">{d["category"]} · {d["date"]}</p><h1>{d["title"]}</h1><div class="story-text"><p class="lead">{d["text"]}</p><p>Conheça os registros e acompanhe o grupo pelo Instagram.</p><a class="button green-button" href="{d["url"]}" target="_blank" rel="noopener">Ver publicação original ↗</a></div><div class="share"><button class="button outline" data-share>Compartilhar história ↗</button><span role="status" id="share-status"></span></div></article>','novidades.html')
write('projetos.html','Ações na comunidade',intro('SERVIR FAZ PARTE','O bem ganha força quando é compartilhado.','Projetos e campanhas que aproximam o escotismo da nossa comunidade.')+'''<section class="wrap section no-top"><div class="project"><span>01</span><div><h2>Coleta de óleo usado</h2><p>Em 2026, o grupo anunciou a continuidade da campanha. Combine a entrega na sede e consulte a possibilidade de retirada de grandes quantidades.</p><a class="text-link" href="contato.html">Combinar uma entrega ↗</a></div></div><div class="project"><span>02</span><div><h2>Solidariedade que mobiliza</h2><p>No Excalicamp de 2023, o grupo conquistou o primeiro lugar na arrecadação destinada ao Lar da Terceira Idade Padre Longino, em Mogi Guaçu.</p><div class="stats"><div><strong>576</strong><span>litros de leite</span></div><div><strong>1.191</strong><span>rolos de papel higiênico</span></div><div><strong>383</strong><span>quilos de açúcar</span></div></div><p class="muted">Resultados históricos da campanha de 2023, divulgados pelo jornal O Município.</p></div></div><div class="project"><span>03</span><div><h2>Cuidado com a nossa cidade</h2><p>O grupo aparece entre os parceiros das Campanhas do Agasalho de 2024 e 2025. Também há registros da campanha Natal Perfumado, voltada a itens de higiene e limpeza.</p><a class="text-link" href="apoie.html">Quero contribuir ↗</a></div></div></section>''')
write('participar.html','Venha conhecer',intro('SUA PRÓXIMA AVENTURA','O primeiro passo é uma conversa.','Quer conhecer o escotismo? A equipe do grupo pode orientar sua primeira visita e explicar como participar.')+'''<section class="wrap section no-top"><div class="steps"><article><span>01</span><h3>Entre em contato</h3><p>Envie uma mensagem pelo Instagram. Conte a idade do interessado e diga que deseja conhecer o grupo.</p></article><article><span>02</span><h3>Combine sua visita</h3><p>Confirme com a equipe o dia, o horário e as orientações para acompanhar uma atividade.</p></article><article><span>03</span><h3>Descubra seu caminho</h3><p>Conheça o ramo, tire suas dúvidas sobre inscrição e receba as orientações para os próximos passos.</p></article></div><div class="cta-box"><h2>Vamos começar?</h2><p>Famílias, jovens e futuros voluntários são bem-vindos para conversar.</p><a class="button orange" href="'''+IG+'''" target="_blank" rel="noopener">Conversar pelo Instagram ↗</a></div><div class="faq"><p class="eyebrow">DÚVIDAS DE QUEM ESTÁ CHEGANDO</p><h2>Antes da primeira visita.</h2><details><summary>Preciso ter experiência com escotismo?</summary><p>Você pode entrar em contato mesmo sem experiência. A equipe explica como funciona a participação.</p></details><details><summary>Quais são os horários?</summary><p>Confirme a programação atual diretamente com o grupo antes de sair de casa. Atividades externas podem alterar o local e o horário dos encontros.</p></details><details><summary>Como saber sobre vagas e contribuições?</summary><p>A equipe orienta individualmente sobre vagas, inscrição, materiais e contribuições. Entre em contato para receber informações atualizadas.</p></details><details><summary>Adultos também podem participar?</summary><p>Sim. O trabalho voluntário faz parte do grupo. Converse com a equipe sobre as funções disponíveis e o processo de formação.</p></details></div></section>''','participar.html')
write('apoie.html','Apoie o grupo',intro('CADA GESTO ABRE UM CAMINHO','Ajude a próxima aventura a acontecer.','Seu apoio fortalece as atividades educativas, os materiais e o cuidado com a nossa sede.')+'''<section class="wrap support-layout section no-top"><div><div class="project"><span>01</span><div><h3>Materiais e equipamentos</h3><p>Contribua com recursos para jogos, oficinas e experiências ao ar livre. Combine previamente a doação de materiais.</p></div></div><div class="project"><span>02</span><div><h3>Cuidado com a sede</h3><p>Serviços, materiais e parcerias ajudam a conservar o espaço de encontro do grupo.</p></div></div><div class="project"><span>03</span><div><h3>Tempo e conhecimento</h3><p>Compartilhe suas habilidades. A equipe pode orientar como colaborar com as atividades e a organização.</p></div></div></div><aside class="donation-card"><p class="eyebrow">APOIE O MARECHAL RONDON</p><h2>Uma contribuição.<br>Muitas possibilidades.</h2><div id="pix-area"><p>Converse com a equipe para conhecer as formas de contribuir e as necessidades atuais do grupo.</p><a class="button orange" href="'''+IG+'''" target="_blank" rel="noopener">Quero ajudar ↗</a></div><p class="small">Obrigado por caminhar com a gente.</p></aside></section>''')
